import { useEffect, useCallback } from 'react';

export const useKeyboardNavigation = (
  containerRef,
  itemSelector,
  onSelect,
  options = {}
) => {
  const {
    horizontal = true,
    vertical = false,
    loop = true,
    homeEnd = true,
    typeAhead = true
  } = options;

  const handleKeyDown = useCallback(
    (event) => {
      const items = Array.from(containerRef.current?.querySelectorAll(itemSelector) || []);
      const currentIndex = items.indexOf(document.activeElement);

      const focusItem = (index) => {
        const targetIndex = loop
          ? (index + items.length) % items.length
          : Math.max(0, Math.min(index, items.length - 1));
        
        items[targetIndex]?.focus();
        onSelect?.(targetIndex);
      };

      switch (event.key) {
        case 'ArrowRight':
          if (horizontal) {
            event.preventDefault();
            focusItem(currentIndex + 1);
          }
          break;

        case 'ArrowLeft':
          if (horizontal) {
            event.preventDefault();
            focusItem(currentIndex - 1);
          }
          break;

        case 'ArrowDown':
          if (vertical) {
            event.preventDefault();
            focusItem(currentIndex + 1);
          }
          break;

        case 'ArrowUp':
          if (vertical) {
            event.preventDefault();
            focusItem(currentIndex - 1);
          }
          break;

        case 'Home':
          if (homeEnd) {
            event.preventDefault();
            focusItem(0);
          }
          break;

        case 'End':
          if (homeEnd) {
            event.preventDefault();
            focusItem(items.length - 1);
          }
          break;

        default:
          if (typeAhead && /^[a-z0-9]$/i.test(event.key)) {
            event.preventDefault();
            const nextMatch = items.findIndex((item, index) => 
              index > currentIndex && 
              item.textContent?.toLowerCase().startsWith(event.key.toLowerCase())
            );
            if (nextMatch !== -1) {
              focusItem(nextMatch);
            } else if (loop) {
              const firstMatch = items.findIndex(item => 
                item.textContent?.toLowerCase().startsWith(event.key.toLowerCase())
              );
              if (firstMatch !== -1) {
                focusItem(firstMatch);
              }
            }
          }
          break;
      }
    },
    [containerRef, itemSelector, onSelect, horizontal, vertical, loop, homeEnd, typeAhead]
  );

  useEffect(() => {
    const container = containerRef.current;
    if (container) {
      container.addEventListener('keydown', handleKeyDown);
      return () => container.removeEventListener('keydown', handleKeyDown);
    }
  }, [containerRef, handleKeyDown]);

  return { handleKeyDown };
};
